/// <summary>
///     The <c>AVAAVAPCMPrintDestinationSettingsFormHandler_Extension</c> class is the extension for <c>AVAPCMPrintDestinationSettingsFormHandler</c>
/// </summary>
[ExtensionOf(classStr(AVAPCMPrintDestinationSettingsFormHandler))]
final public static class AVAAVAPCMPrintDestinationSettingsFormHandler_Extension
{
}

Method.Source:
/// <summary>
/// When email setup is modified, update the subject.
/// </summary>
/// <param name="sender">
///     FormControl
/// </param>
/// <param name="e">
///     Event arguments
/// </param>
public static void AVAPCMEmailSetup_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormStringControl       locFormStringControlAVAPCMEmailSetup;
    FormRun                 locFormRun;
    FormStringControl       locFormStringControlMailSubject;
    FormStringControl       locFormStringControlMailTo;
    FormStringControl       locFormStringControlMailFormat;
    //FormStaticTextControl   locFormStringControlMailBody;
    FormControl             locEmailBodyEditor;

    LanguageId              locLanguageId;

    AVAPCMEmailSetup        locAVAPCMEmailSetup;
    AVAPCMEmailSetupId      locAVAPCMEmailSetupId;
    SysEmailTable           locSysEmailTable;
    SysEmailMessageTable    locSysEmailMessageTable;
    /*
    str                         locAttachmentFileName;
    str                         locEmailTo;
    str                         locEmailSubject;
    str                         locEmailBody;
    InventSite                  locInventSite;
    */

    next AVAPCMEmailSetup_OnModified(sender, e);

    locFormStringControlAVAPCMEmailSetup    = sender as FormStringControl;
    locFormRun                              = locFormStringControlAVAPCMEmailSetup.formRun();
    locFormStringControlMailSubject         = locFormRun.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, MailSubject)) as FormStringControl;
    locFormStringControlMailTo              = locFormRun.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, MailTo)) as FormStringControl;
    locFormStringControlMailFormat          = locFormRun.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, MailFormat)) as FormStringControl;
    //locFormStringControlMailBody            = locFormRun.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, EmailBodyText)) as FormStaticTextControl;
    locEmailBodyEditor                      = locFormRun.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, EmailBodyEditor)) as FormControl;

    locLanguageId                           = CompanyInfo::find().LanguageId;

    if (locFormStringControlAVAPCMEmailSetup.text())
    {
        locFormStringControlMailSubject.allowEdit(false);
        locAVAPCMEmailSetupId   = locFormStringControlAVAPCMEmailSetup.text();
        if(locAVAPCMEmailSetupId)
        {
            locAVAPCMEmailSetup     = AVAPCMEmailSetup::find(locAVAPCMEmailSetupId);
            locSysEmailTable        = SysEmailTable::find(locAVAPCMEmailSetup.EmailId);
            if(locSysEmailTable.DefaultLanguage)
            {
                locLanguageId       = locSysEmailTable.DefaultLanguage;
            }
            locSysEmailMessageTable = SysEmailMessageTable::find(locAVAPCMEmailSetup.EmailId, locLanguageId);
        }
        if(locSysEmailMessageTable)
        {
            locFormStringControlMailSubject.text(locSysEmailMessageTable.Subject);
        }
        else
        {
            locFormStringControlMailSubject.text(locFormStringControlAVAPCMEmailSetup.text());
        }
    }
    else
    {
        locFormStringControlMailSubject.allowEdit(true);
        locFormStringControlMailSubject.text('');
    }
}

/// <summary>
/// When the form is initialized, check email setup
/// </summary>
/// <param name="args">Pre/post arguments</param>
public static void SRSPrintDestinationSettingsForm_Post_init(XppPrePostArgs args)
{
    FormRun             locFormRun;
    FormStringControl   locFormStringControl;

    locFormRun = args.getThis() as FormRun;

    locFormStringControl = locFormRun.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, AVAPCMEmailSetup)) as FormStringControl;
    locFormStringControl.text(AVASalesParameters::find().EmailSetupId);
    locFormStringControl.modified();

    next SRSPrintDestinationSettingsForm_Post_init(args);
}
